import { sql } from 'drizzle-orm';
import {
  bigint,
  index,
  integer,
  jsonb,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';
import { uuidv7 } from 'uuidv7';

/*
 * Conventions
 *  - Primary keys: UUIDv7 generated by the application (time-ordered, safe to expose).
 *  - Timestamps: timestamptz, UTC.
 *  - Everything that lives in the game world carries `world_id`, even though
 *    there is a single shared world today.
 *  - JSONB only for data whose shape is expected to evolve (e.g. appearance,
 *    event payloads), never for data we need to join or constrain on.
 *  - Text enums are constrained in the application (zod); see DATABASE.md.
 */

const id = () =>
  uuid('id')
    .primaryKey()
    .$defaultFn(() => uuidv7());
const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();
const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

// ---------------------------------------------------------------------------
// Accounts & sessions (out-of-game identity)
// ---------------------------------------------------------------------------
export const accounts = pgTable(
  'accounts',
  {
    id: id(),
    /** Stored lower-cased and trimmed. */
    email: text('email').notNull(),
    passwordHash: text('password_hash').notNull(),
    /** 'active' | 'suspended' | 'banned' */
    status: text('status').notNull().default('active'),
    lastLoginAt: timestamp('last_login_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex('accounts_email_uq').on(t.email)],
);

export const sessions = pgTable(
  'sessions',
  {
    id: id(),
    accountId: uuid('account_id')
      .notNull()
      .references(() => accounts.id, { onDelete: 'cascade' }),
    /** SHA-256 of the opaque session token; the token itself is never stored. */
    tokenHash: text('token_hash').notNull(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    lastSeenAt: timestamp('last_seen_at', { withTimezone: true }).notNull().defaultNow(),
    ip: text('ip'),
    userAgent: text('user_agent'),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex('sessions_token_hash_uq').on(t.tokenHash),
    index('sessions_account_idx').on(t.accountId),
    index('sessions_expires_idx').on(t.expiresAt),
  ],
);

// ---------------------------------------------------------------------------
// World
// ---------------------------------------------------------------------------
export const worlds = pgTable(
  'worlds',
  {
    id: id(),
    slug: text('slug').notNull(),
    name: text('name').notNull(),
    /** 'open' | 'maintenance' | 'closed' */
    status: text('status').notNull().default('open'),
    /** Monotonic simulation tick, advanced only by the world worker. */
    tick: bigint('tick', { mode: 'number' }).notNull().default(0),
    lastTickAt: timestamp('last_tick_at', { withTimezone: true }),
    /** Hex where new characters appear. */
    spawnQ: integer('spawn_q').notNull().default(0),
    spawnR: integer('spawn_r').notNull().default(0),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex('worlds_slug_uq').on(t.slug)],
);

// ---------------------------------------------------------------------------
// Characters (in-game identity). An account owns many; plays one at a time.
// ---------------------------------------------------------------------------
export const characters = pgTable(
  'characters',
  {
    id: id(),
    accountId: uuid('account_id')
      .notNull()
      .references(() => accounts.id, { onDelete: 'cascade' }),
    worldId: uuid('world_id')
      .notNull()
      .references(() => worlds.id, { onDelete: 'restrict' }),
    name: text('name').notNull(),
    /** Versioned JSON, see CharacterAppearance in @realms/shared. */
    appearance: jsonb('appearance').notNull(),
    /** Axial hex coordinates of the character on the world map. */
    hexQ: integer('hex_q').notNull(),
    hexR: integer('hex_r').notNull(),
    lastPlayedAt: timestamp('last_played_at', { withTimezone: true }),
    /** Soft delete: the world's history may still reference this character. */
    deletedAt: timestamp('deleted_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('characters_account_idx')
      .on(t.accountId)
      .where(sql`${t.deletedAt} is null`),
    // Case-insensitive unique name per world among living characters.
    uniqueIndex('characters_world_name_uq')
      .on(t.worldId, sql`lower(${t.name})`)
      .where(sql`${t.deletedAt} is null`),
    index('characters_world_hex_idx').on(t.worldId, t.hexQ, t.hexR),
  ],
);

// ---------------------------------------------------------------------------
// World events: append-only log of meaningful things that happened.
// Audit trail today; the backbone of world history / world-changing events later.
// ---------------------------------------------------------------------------
export const worldEvents = pgTable(
  'world_events',
  {
    id: id(),
    worldId: uuid('world_id')
      .notNull()
      .references(() => worlds.id, { onDelete: 'restrict' }),
    /** Dotted event type, e.g. 'character.created'. */
    type: text('type').notNull(),
    actorAccountId: uuid('actor_account_id').references(() => accounts.id, {
      onDelete: 'set null',
    }),
    actorCharacterId: uuid('actor_character_id').references(() => characters.id, {
      onDelete: 'set null',
    }),
    payload: jsonb('payload').notNull().default({}),
    createdAt: createdAt(),
  },
  (t) => [
    index('world_events_world_time_idx').on(t.worldId, t.createdAt),
    index('world_events_type_idx').on(t.type),
  ],
);

export type Account = typeof accounts.$inferSelect;
export type Session = typeof sessions.$inferSelect;
export type World = typeof worlds.$inferSelect;
export type Character = typeof characters.$inferSelect;
export type WorldEvent = typeof worldEvents.$inferSelect;
